@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="infinite-scroll-container" @ref="_containerRef">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinelRef" class="infinite-scroll-sentinel">
            @if (_isLoading)
            {
                <div class="infinite-scroll-spinner" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            }
        </div>
    }
</div>

@code {
    private ElementReference _containerRef;
    private ElementReference _sentinelRef;
    private IJSObjectReference? _module;
    private IJSObjectReference? _observer;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotNetRef;
    private bool _isLoading;
    private bool _initialized;

    /// <summary>The collection of items to display.</summary>
    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    /// <summary>Whether more items are available to load.</summary>
    [Parameter]
    public bool HasMore { get; set; }

    /// <summary>Callback invoked when more items should be loaded.</summary>
    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    /// <summary>Template for rendering each item.</summary>
    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    /// <summary>
    /// Distance from the bottom (in CSS pixels) at which loading is triggered.
    /// Maps to the IntersectionObserver rootMargin bottom value.
    /// </summary>
    [Parameter]
    public int LoadThreshold { get; set; } = 100;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/InfiniteScrollList.razor.js");

            await SetupObserver();
            _initialized = true;
        }
        else if (_initialized && HasMore)
        {
            // Re-observe after new items are rendered (sentinel element may have been recreated)
            await SetupObserver();
        }
    }

    private async Task SetupObserver()
    {
        // Dispose previous observer if any
        if (_observer is not null)
        {
            await _observer.InvokeVoidAsync("disconnect");
            await _observer.DisposeAsync();
            _observer = null;
        }

        if (_module is not null && HasMore)
        {
            _observer = await _module.InvokeAsync<IJSObjectReference>(
                "createObserver", _sentinelRef, _dotNetRef, LoadThreshold);
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_observer is not null)
        {
            await _observer.InvokeVoidAsync("disconnect");
            await _observer.DisposeAsync();
        }
        _module?.DisposeAsync().AsTask().Ignore();
        _dotNetRef?.Dispose();
    }
}

/**
 * Creates an IntersectionObserver that calls back into .NET when the sentinel
 * element becomes visible, indicating the user has scrolled near the bottom.
 *
 * @param {Element} sentinel - The DOM element to observe.
 * @param {object} dotNetRef - A DotNetObjectReference for JS interop callbacks.
 * @param {number} threshold - Extra margin (px) below the viewport to trigger early.
 * @returns {IntersectionObserver} The observer instance (returned so Blazor can call disconnect).
 */
export function createObserver(sentinel, dotNetRef, threshold) {
    const observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                if (entry.isIntersecting) {
                    dotNetRef.invokeMethodAsync("OnSentinelVisible");
                }
            }
        },
        {
            rootMargin: `0px 0px ${threshold}px 0px`,
        }
    );

    observer.observe(sentinel);
    return observer;
}

.infinite-scroll-container {
    overflow-y: auto;
}

.infinite-scroll-sentinel {
    display: flex;
    justify-content: center;
    padding: 1rem 0;
    min-height: 1px; /* ensure the element is observable even when empty */
}

.infinite-scroll-spinner {
    width: 2rem;
    height: 2rem;
    border: 0.25rem solid currentColor;
    border-right-color: transparent;
    border-radius: 50%;
    animation: infinite-scroll-spin 0.75s linear infinite;
}

@keyframes infinite-scroll-spin {
    to {
        transform: rotate(360deg);
    }
}

